SELECT page, AVG(duration_sec) AS avg_duration_sec, COUNT(DISTINCT page) AS distinct_pages, MIN(duration_sec) AS min_duration_sec, PERCENTILE_APPROX(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, MAX(duration_sec) FILTER (WHERE page = '/product') AS product_max_duration_sec FROM web_events GROUP BY 1 HAVING AVG(duration_sec) < 1000000 ORDER BY distinct_pages DESC NULLS FIRST;
